insert into portfolio.systems (slug, sort, name, summary, domains, stack, ships_as, platform, org, internal, links, logo, screen, points, architecture) values
  ('ramanujan', 0, 'Ramanujan', 'An AI analytics copilot: business teams ask questions in plain English inside Microsoft Teams and get answers from enterprise data in seconds, with no SQL and no dashboards.', array['ai', 'api']::text[], array['Python', 'FastAPI', 'Gemini', 'Vertex AI', 'BigQuery', 'Qdrant', 'Sentence-Transformers', 'Microsoft Graph API', 'Docker']::text[], 'Agentic assistant · Microsoft Teams', 'service', null, false, null, null, null, array['A Gemini ReAct agent turns natural-language questions into governed BigQuery SQL.', 'RAG over a Qdrant-backed KPI glossary with sentence-transformer embeddings, so answers match the business definition of each metric.', 'A production FastAPI service on Vertex AI with hexagonal architecture.', 'Safety layers: a SQL policy engine with row-level access control, and grounding guardrails against hallucinated answers.']::text[], '{"edges":[{"to":"api","from":"teams","label":"ask"},{"to":"agent","from":"api"},{"to":"agent","from":"rag","label":"KPI definitions"},{"to":"policy","from":"agent","label":"SQL"},{"to":"bq","from":"policy","label":"governed query"},{"to":"teams","from":"api","label":"grounded answer","dashed":true}],"nodes":[{"x":0,"y":1,"id":"teams","label":"Microsoft Teams","layer":"interface","detail":"Questions in plain English"},{"x":1,"y":1,"id":"api","label":"FastAPI service","layer":"api","detail":"Vertex AI, hexagonal"},{"x":2,"y":1,"id":"agent","label":"Gemini ReAct agent","layer":"automation","detail":"Question to SQL"},{"x":2,"y":2,"id":"rag","label":"KPI glossary (RAG)","layer":"data","detail":"Qdrant + embeddings"},{"x":3,"y":1,"id":"policy","label":"SQL policy engine","layer":"automation","detail":"Row-level access"},{"x":4,"y":1,"id":"bq","label":"BigQuery","layer":"data","detail":"Enterprise data"}],"caption":"Simplified from the project description."}'::jsonb),
  ('safety-stock', 1, 'Safety-Stock Intelligence', 'An ML-driven demand planning and inventory optimisation platform for Tata Steel and Hindustan Zinc: MRP tagging, demand classification and safety-stock computation for intermittent, lumpy industrial demand.', array['ai', 'automation']::text[], array['Python', 'FastAPI', 'Dash', 'Prophet', 'LightGBM', 'Pandas', 'MySQL', 'Docker']::text[], 'Internal · Moglix', 'internal', 'Moglix', true, null, null, null, array['One pipeline for MRP tagging, vendor lead time and ML-based MRP levels, replacing separate batch workflows.', 'Demand classified with the Syntetos-Boylan framework (ADI, CV²); safety stock from Prophet, statistical models and compound Poisson modelling with newsvendor cost asymmetry.', 'Raised Tata Steel''s OTIF from below 50% to over 70%, earning Moglix''s Jungle Torchbearer Award.', 'A Dockerised FastAPI platform with a Dash dashboard: model comparison, live recomputation, filters and Excel export.']::text[], null),
  ('supplierinv', 2, 'SupplierInv', 'An invoice intelligence pipeline that extracts, validates and reconciles supplier invoices at scale with generative AI.', array['ai', 'automation']::text[], array['Python', 'Gemini', 'AWS Textract', 'Pydantic', 'Kafka', 'MongoDB', 'BigQuery', 'Power BI']::text[], 'Internal · Moglix', 'internal', 'Moglix', true, null, null, null, array['Gemini and AWS Textract turn unstructured invoices into schema-validated data.', 'A real-time Kafka → MongoDB → BigQuery backbone streams it at enterprise scale.', 'Automated reconciliation (fuzzy item matching, tolerance bands, HSN and GSTIN checks) replaces hours of manual review.', 'Results feed live Power BI dashboards for procurement analytics.']::text[], null),
  ('procurement-agent', 3, 'Conversational Procurement', 'An AI procurement assistant on WhatsApp: people work through sourcing workflows in natural-language conversations.', array['ai', 'api']::text[], array['Python', 'FastAPI', 'WhatsApp Business API', 'Agentic AI', 'REST APIs']::text[], 'Internal · Moglix', 'internal', 'Moglix', true, null, null, null, array['A WhatsApp-integrated AI agent for conversational procurement workflows.', 'Backend services and agent orchestration that process requests, run sourcing workflows and reply with context.']::text[], null),
  ('ocr-accuracy-report-pipeline', 4, 'OCR Accuracy Report Pipeline', 'A reporting pipeline that measures OCR accuracy at Moglix.', array['ai', 'automation']::text[], array['Python', 'OCR']::text[], 'Internal · Moglix', 'internal', 'Moglix', true, null, null, null, null, null),
  ('bakup', 5, 'Bakup', 'A self-hosted, Git-like backup system: take local snapshots, push them to your own server when you are online, and restore any earlier version. Offline-first and deduplicated.', array['automation', 'tools', 'infra']::text[], array['Python', 'FastAPI', 'SQLite', 'Docker', 'Docker Compose', 'SHA-256', 'HTML · CSS · JS']::text[], 'CLI + server · Windows, Linux, Python', 'web', null, false, '[{"href":"https://bakup.mohammadramiz.in/","label":"bakup.mohammadramiz.in"},{"href":"https://github.com/RamizMohammad/Bakup-Release/releases","label":"Releases on GitHub"}]'::jsonb, null, '{"src":"/images/screens/bakup.webp","kind":"web","width":1024,"height":640}'::jsonb, array['Versioned snapshots and secure server sync, with SHA-256 content-addressable storage for deduplication.', 'CLI tools for init, commit, push, clone and restore, packaged for Windows, Linux and Python.', 'A FastAPI backend, a web dashboard and token-based authentication, deployed with Docker.']::text[], '{"edges":[{"to":"snap","from":"cli","label":"commit"},{"to":"api","from":"snap","label":"push"},{"to":"api","from":"web"},{"to":"store","from":"api","label":"objects"},{"to":"db","from":"api","label":"metadata"},{"to":"docker","from":"api","label":"runs in","dashed":true}],"nodes":[{"x":0,"y":0,"id":"cli","label":"Bakup CLI","layer":"interface","detail":"init, commit, push…"},{"x":0,"y":2,"id":"web","label":"Web dashboard","layer":"interface","detail":"Browse and restore"},{"x":1,"y":0,"id":"snap","label":"Local snapshots","layer":"automation","detail":"Offline-first"},{"x":2,"y":1,"id":"api","label":"FastAPI server","layer":"api","detail":"Token auth"},{"x":3,"y":0,"id":"store","label":"Content store","layer":"data","detail":"SHA-256, deduplicated"},{"x":3,"y":2,"id":"db","label":"SQLite","layer":"data","detail":"Snapshot metadata"},{"x":4,"y":1,"id":"docker","label":"Docker","layer":"infra","detail":"Self-hosted"}],"caption":"Simplified from the project description."}'::jsonb),
  ('snapy', 6, 'Snapy', 'A one-click tool that captures an Android phone''s full state to a PC and restores it after a wipe or OS reinstall, with no root access.', array['tools', 'apps']::text[], array['Python', 'ADB', 'PySide6', 'Qt', 'CLI tooling']::text[], 'Desktop app + CLI · Loopax Technologies', 'desktop', null, false, '[{"href":"https://github.com/RamizMohammad/snapy/releases","label":"Releases on GitHub"}]'::jsonb, null, null, array['A snapshot-and-restore engine that runs entirely over ADB, so it works on stock, unrooted phones.', 'Wipe, reinstall and bring a phone back to its earlier state without a cloud account or rooting.', 'Shipped as a Loopax Technologies product with a Python CLI and a PySide6 desktop app, prototyped in Google Stitch and rebuilt natively for Windows.']::text[], '{"caption":"Simplified from the project description.","nodes":[{"id":"gui","label":"PySide6 app","detail":"Windows desktop","layer":"interface","x":0,"y":0},{"id":"cli","label":"Python CLI","detail":"Scriptable","layer":"interface","x":0,"y":2},{"id":"engine","label":"Snapshot engine","detail":"Backup and restore","layer":"automation","x":1,"y":1},{"id":"adb","label":"ADB","detail":"No root needed","layer":"api","x":2,"y":1},{"id":"phone","label":"Android phone","detail":"Stock, unrooted","layer":"infra","x":3,"y":0},{"id":"snap","label":"Snapshot on PC","detail":"Full phone state","layer":"data","x":3,"y":2}],"edges":[{"from":"gui","to":"engine"},{"from":"cli","to":"engine"},{"from":"engine","to":"adb"},{"from":"adb","to":"phone","label":"read / restore"},{"from":"engine","to":"snap","label":"save"}]}'::jsonb),
  ('buddycode', 7, 'BuddyCode', 'A real-time collaborative code editor with syntax highlighting, multiple languages and live cursor sharing.', array['tools']::text[], array['Python', 'Flask', 'WebSocket', 'CodeMirror']::text[], 'Web app', 'web', null, false, '[{"href":"https://www.buddycode.online","label":"buddycode.online"}]'::jsonb, '/images/logos/buddycode.webp', null, array['Several people edit the same file at once and see each other''s cursors.', 'Edits travel over WebSocket between the browser editor and a Flask server.', 'CodeMirror provides the editor and syntax highlighting for multiple languages.', 'An Android companion app runs Python code as an online compiler.']::text[], '{"edges":[{"to":"socket","from":"editor","label":"edits"},{"to":"socket","from":"peer","label":"edits"},{"to":"server","from":"socket"},{"to":"runner","from":"server","label":"run"},{"to":"peer","from":"server","label":"broadcast","dashed":true}],"nodes":[{"x":0,"y":0,"id":"editor","label":"Browser editor","layer":"interface","detail":"CodeMirror editor"},{"x":0,"y":2,"id":"peer","label":"Peer editor","layer":"interface","detail":"Second collaborator"},{"x":1,"y":1,"id":"socket","label":"WebSocket channel","layer":"api","detail":"Edits and cursors"},{"x":2,"y":1,"id":"server","label":"Flask server","layer":"api","detail":"Sessions and broadcast"},{"x":3,"y":1,"id":"runner","label":"Python runner","layer":"automation","detail":"Executes code"}],"caption":"Simplified from the project description."}'::jsonb),
  ('linkium', 8, 'Linkium', 'A cross-platform tool that connects devices for file sharing and communication.', array['tools']::text[], array['Python', 'Tkinter', 'WebSocket', 'Networking']::text[], 'Desktop app', 'desktop', null, false, '[{"href":"https://www.linkium.space","label":"linkium.space"}]'::jsonb, '/images/logos/linkium.webp', null, array['Pairs two devices and keeps a live connection between them.', 'Moves files and messages over a WebSocket link.', 'Desktop interface built with Tkinter.']::text[], '{"edges":[{"to":"link","from":"a"},{"to":"transfer","from":"link"},{"to":"msg","from":"link"},{"to":"b","from":"transfer"},{"to":"b","from":"msg"}],"nodes":[{"x":0,"y":1,"id":"a","label":"Device A","layer":"interface","detail":"Tkinter desktop app"},{"x":1,"y":1,"id":"link","label":"WebSocket link","layer":"api","detail":"Two-way channel"},{"x":2,"y":0,"id":"transfer","label":"File transfer","layer":"automation","detail":"Sends files"},{"x":2,"y":2,"id":"msg","label":"Messages","layer":"automation","detail":"Device messages"},{"x":3,"y":1,"id":"b","label":"Device B","layer":"interface","detail":"Tkinter desktop app"}],"caption":"Simplified from the project description."}'::jsonb),
  ('backup-engine', 9, 'Backup Engine', 'A backup automation tool that takes compressed snapshots of important folders and tracks file changes by hashing.', array['automation', 'tools']::text[], array['Python', 'PyQt', 'Multithreading', 'File hashing']::text[], 'Desktop release v1.0', 'desktop', null, false, '[{"href":"https://github.com/RamizMohammad/Backup_Engine/releases/tag/v1.0","label":"Release v1.0 on GitHub"}]'::jsonb, '/images/logos/backup-engine.webp', null, array['Hashes files to detect what changed since the last run.', 'Writes compressed snapshots of the folders you choose.', 'Runs work on background threads so the PyQt interface stays responsive.']::text[], '{"edges":[{"to":"workers","from":"ui","label":"start"},{"to":"hash","from":"workers"},{"to":"snap","from":"hash","label":"changed files"},{"to":"store","from":"snap"},{"to":"ui","from":"workers","label":"progress","dashed":true}],"nodes":[{"x":0,"y":1,"id":"ui","label":"PyQt interface","layer":"interface","detail":"Folders and progress"},{"x":1,"y":1,"id":"workers","label":"Worker threads","layer":"automation","detail":"Background jobs"},{"x":2,"y":0,"id":"hash","label":"Change detection","layer":"automation","detail":"File hashing"},{"x":2,"y":2,"id":"snap","label":"Snapshot writer","layer":"data","detail":"Compressed archives"},{"x":3,"y":1,"id":"store","label":"Backup location","layer":"infra","detail":"Disk or drive"}],"caption":"Simplified from the project description."}'::jsonb),
  ('confess', 10, 'Confess', 'A privacy-focused anonymous social platform for sharing confessions, thoughts and experiences, with real-time feeds and reactions. Published on Google Play.', array['apps', 'api']::text[], array['Android', 'Java', 'Firebase', 'Firestore', 'Cloud Functions', 'FCM', 'AWS', 'Cloudinary']::text[], 'Android · Google Play', 'android', null, false, '[{"href":"https://play.google.com/store/apps/details?id=in.mohammad.ramiz.confess","label":"Google Play"}]'::jsonb, '/images/logos/confess-app.webp', '{"src":"/images/screens/confess-app.webp","kind":"phone","width":1024,"height":512}'::jsonb, array['Google Sign-In, end-to-end encryption and biometric authentication keep users private.', 'Real-time Firebase listeners update the feed instantly.', 'Cloud Functions handle content moderation.', 'Push notifications through Firebase Cloud Messaging.']::text[], '{"caption":"Simplified from the project description.","nodes":[{"id":"app","label":"Android app","detail":"Java · biometric lock","layer":"interface","x":0,"y":1},{"id":"auth","label":"Google Sign-In","detail":"Account login","layer":"api","x":1,"y":0},{"id":"db","label":"Firestore","detail":"Confessions, reactions","layer":"data","x":1,"y":2},{"id":"fn","label":"Cloud Functions","detail":"Content moderation","layer":"automation","x":2,"y":2},{"id":"fcm","label":"Cloud Messaging","detail":"Push notifications","layer":"infra","x":3,"y":1}],"edges":[{"from":"app","to":"auth","label":"sign in"},{"from":"app","to":"db","label":"post"},{"from":"db","to":"fn","label":"on write"},{"from":"fn","to":"fcm","label":"notify"},{"from":"fcm","to":"app","label":"push","dashed":true}]}'::jsonb),
  ('confess-web', 11, 'Confess Web', 'The promotional website for the Confess Android app: platform highlights and a direct way to download the app.', array['apps']::text[], array['React', 'Vite', 'TypeScript', 'Framer Motion', 'Tailwind CSS']::text[], 'Web', 'web', null, false, '[{"href":"https://confess.mohammadramiz.in/","label":"confess.mohammadramiz.in"}]'::jsonb, '/images/logos/confess-web.webp', '{"src":"/images/screens/confess-web.webp","kind":"web","width":1024,"height":640}'::jsonb, null, null),
  ('timefold', 12, 'Time Fold', 'A timeline website showing historical events that happened on today''s date.', array['api']::text[], array['Python', 'FastAPI', 'Data processing']::text[], 'Web app', 'web', null, false, '[{"href":"https://www.timefold.space/","label":"timefold.space"}]'::jsonb, '/images/logos/timefold.webp', '{"src":"/images/screens/timefold.webp","kind":"web","width":1024,"height":640}'::jsonb, null, '{"caption":"Simplified from the project description.","nodes":[{"id":"page","label":"Web page","detail":"Today''s date","layer":"interface","x":0,"y":1},{"id":"api","label":"FastAPI service","detail":"Events by date","layer":"api","x":1,"y":1},{"id":"proc","label":"Data processing","detail":"Python","layer":"automation","x":2,"y":1},{"id":"src","label":"Wikipedia","detail":"Historical events","layer":"data","x":3,"y":1}],"edges":[{"from":"page","to":"api","label":"today"},{"from":"api","to":"proc"},{"from":"proc","to":"src","label":"source"},{"from":"api","to":"page","label":"events","dashed":true}]}'::jsonb);
